21	    public function validate(int|float|bool|string|array|null $value, OperationResult $result, APIParameterInterface $param) : void
22	    {
23	        if($value === null || $value === '') {
24	            // Nothing to validate
25	            return;
26	        }
27	
28	        if(!is_string($value)) {
29	            // Non-string values are skipped; type enforcement is handled by other validators
30	            return;
31	        }
32	
33	        if(mb_strlen($value) > $this->maxLength) {
34	            $result->makeError(
35	                sprintf(
36	                    'The value for API parameter `%s` exceeds the maximum allowed length of %d character(s). '.PHP_EOL.
37	                    'Actual length: %d character(s).',
38	                    $param->getName(),
39	                    $this->maxLength,
40	                    mb_strlen($value)
41	                ),
42	                ParamValidationInterface::VALIDATION_MAX_LENGTH_EXCEEDED
43	            );
44	        }
45	    }
46	}

